import base64, json
tok = ""
tok += "=" * (-len(tok) % 4)
d = json.loads(base64.b64decode(tok))
open("access_token.txt","w").write(d["access_token"])
print("user_id:", d["user_id"], "| account_type:", d["account_type"], "| expires_at:", d["expires_at"])
print("access_token saved, len:", len(d["access_token"]))
